html:
{%- import "costeo_yelke/templates/print/oc_yelke.html" as oc -%}
{#- Cotización. En modo "Volumen" (custom_tipo_formato) muestra precios por rango de piezas. Diseño: templates/print/oc_yelke.html -#}
{{ oc.estilos() }}
{{ oc.membrete_encabezado(doc, no_letterhead, print_settings, "Cotización") }}
<div class="pdf-container">
{{ oc.marca_borrador(doc) }}
{%- set es_volumen = (doc.get("custom_tipo_formato") == "Volumen") -%}
{{ oc.datos(doc, {"etiqueta": "Cliente", "nombre": doc.customer_name or doc.party_name, "rfc": rfc_tercero("Customer", doc.party_name), "direccion": direccion_lineas(doc.customer_address)},
    [("Fecha", fecha_corta(doc.transaction_date)),
     ("Válida hasta", fecha_corta(doc.valid_till)),
     ("Tipo", "Precios por volumen" if es_volumen else None),
     ("Moneda", doc.currency)]) }}
{% if es_volumen %}
{% if es_volumen %}
        {# Obtener todas las reglas de precios del primer item para determinar las columnas #}
        {% set primer_item = doc.items[0] if doc.items else None %}
        {% set columnas_precios = [] %}

        {% if primer_item %}
            {% set rules_base = frappe.get_all("Pricing Rule", 
                filters={
                    "item_code": primer_item.item_code, 
                    "disable": 0,
                    "selling": 1,
                    "min_qty": [">", 0]
                }, 
                fields=["min_qty", "max_qty", "apply_discount_on", "rate", "discount_percentage", "discount_amount", "for_price_list"], 
                order_by="min_qty asc") 
            %}

            {# Construir columnas dinámicas #}
            {% for rule in rules_base %}
                {% if rule.max_qty and rule.max_qty > 0 %}
                    {% set _ = columnas_precios.append({
                        "titulo": rule.min_qty|int|string + " - " + rule.max_qty|int|string + " pzas",
                        "min_qty": rule.min_qty,
                        "max_qty": rule.max_qty,
                        "indice": loop.index0
                    }) %}
                {% else %}
                    {% set _ = columnas_precios.append({
                        "titulo": rule.min_qty|int|string + "+ pzas",
                        "min_qty": rule.min_qty,
                        "max_qty": rule.max_qty,
                        "indice": loop.index0
                    }) %}
                {% endif %}
            {% endfor %}
        {% endif %}

        {# Calcular ancho de columnas dinámicamente #}
        {% set num_columnas = columnas_precios|length %}
        {% set ancho_columnas_precio = (60 / num_columnas)|int if num_columnas > 0 else 20 %}
    {% endif %}

    <table class="table items-table">
        <thead>
            <tr>
                <th class="text-center" width="5%">#</th>
                <th class="text-center" width="10%">Img</th>

                <th width="{% if es_volumen %}25%{% else %}25%{% endif %}">Artículo</th>

                {% if not es_volumen %}
                    <th width="25%">Descripción</th>

                    <th class="text-center" width="5%">Cant.</th> 
                    <th class="text-right" width="15%">P. Unitario</th>
                    <th class="text-right" width="15%">Importe</th>

                {% else %}
                    {# Generar columnas dinámicas para volumen #}
                    {% for columna in columnas_precios %}
                        <th class="text-center bg-volumen" width="{{ ancho_columnas_precio }}%">
                            {{ columna.titulo }}
                        </th>
                    {% endfor %}
                {% endif %}
            </tr>
        </thead>
        <tbody>
            {% for row in doc.items %}
            <tr>
                <td class="text-center">{{ row.idx }}</td>
                <td class="text-center item-image-cell">
                    {% if row.image %}
                        <img src="{{ row.image }}" alt="Img" class="item-image" />
                    {% else %}
                        -
                    {% endif %}
                </td>

                <td>
                    <strong class="item-title">{{ row.item_name or row.item_code }}</strong>

                    {% if row.item_code %}
                        <div class="item-code"><strong>Código:</strong> {{ row.item_code }}</div>
                    {% endif %}

                    {% if row.mx_product_service_key %}
                        <div class="item-fiscal-code"><strong>SAT:</strong> {{ row.mx_product_service_key }}</div>
                    {% endif %}

                    <div style="font-size:9px; color:#555; margin-top:2px;">
                        <strong>U.M.:</strong> {{ row.uom or row.stock_uom or "PZ" }}
                    </div>
                </td>

                {% if not es_volumen %}
                    <td>
                        <div class="item-description">{{ row.description }}</div>
                    </td>

                    <td class="text-center">
                        {{ row.qty }}
                    </td>

                    <td class="text-right">
                        {{ row.get_formatted("rate", doc) or "{:,.2f}".format(row.rate) }}
                    </td>
                    <td class="text-right">
                        <strong>{{ row.get_formatted("amount", doc) or "{:,.2f}".format(row.amount) }}</strong>
                    </td>

                {% else %}
                    {# Obtener reglas de precios para este item específico #}
                    {# Incluimos for_price_list para los modos de descuento que lo necesitan #}
                    {% set rules = frappe.get_all("Pricing Rule", 
                        filters={
                            "item_code": row.item_code, 
                            "disable": 0,
                            "selling": 1,
                            "min_qty": [">", 0]
                        }, 
                        fields=["min_qty", "max_qty", "apply_discount_on", "rate", "discount_percentage", "discount_amount", "for_price_list"], 
                        order_by="min_qty asc") 
                    %}

                    {# Iterar columnas por indice posicional — mismo orden que rules (min_qty asc) #}
                    {% for columna in columnas_precios %}
                        <td class="text-center volume-cell">
                            {% for rule in rules %}{% if loop.index0 == columna.indice %}

                                {# Detectar tipo por el campo que tenga valor, sin depender del string apply_discount_on #}
                                {% if rule.rate and rule.rate > 0 and rule.apply_discount_on == "Rate" %}
                                    {{ doc.currency }} {{ "{:,.2f}".format(rule.rate) }}

                                {% elif rule.discount_percentage and rule.discount_percentage > 0 %}
                                    {% set item_prices = frappe.get_all("Item Price",
                                        filters={"item_code": row.item_code, "price_list": rule.for_price_list, "selling": 1},
                                        fields=["price_list_rate"], limit=1) if rule.for_price_list else [] %}
                                    {% set precio_base = item_prices[0].price_list_rate if item_prices else (row.price_list_rate or row.rate) %}
                                    {{ doc.currency }} {{ "{:,.2f}".format(precio_base * (1 - rule.discount_percentage / 100)) }}
                                    <div style="font-size:8px; color:#888;">({{ "{:.0f}".format(rule.discount_percentage) }}% dto.)</div>

                                {% elif rule.discount_amount and rule.discount_amount > 0 %}
                                    {% set item_prices = frappe.get_all("Item Price",
                                        filters={"item_code": row.item_code, "price_list": rule.for_price_list, "selling": 1},
                                        fields=["price_list_rate"], limit=1) if rule.for_price_list else [] %}
                                    {% set precio_base = item_prices[0].price_list_rate if item_prices else (row.price_list_rate or row.rate) %}
                                    {% set precio_final = precio_base - rule.discount_amount %}
                                    {{ doc.currency }} {{ "{:,.2f}".format(precio_final if precio_final > 0 else 0) }}
                                    <div style="font-size:8px; color:#888;">(-{{ doc.currency }} {{ "{:,.2f}".format(rule.discount_amount) }})</div>

                                {% elif rule.rate and rule.rate > 0 %}
                                    {{ doc.currency }} {{ "{:,.2f}".format(rule.rate) }}

                                {% else %}
                                    -
                                {% endif %}

                            {% endif %}{% endfor %}
                        </td>
                    {% endfor %}
                {% endif %}
            </tr>
            {% endfor %}
        </tbody>
    </table>
{% else %}
{{ oc.tabla_articulos(doc) }}
{% endif %}
{{ oc.cierre(doc, mostrar_pagos=not es_volumen, mostrar_totales=not es_volumen) }}
</div>
{{ oc.membrete_pie(doc, no_letterhead, print_settings) }}
